#!/usr/bin/env python3
"""Render every generated file in the repository from a :class:`model.Catalog`.

Pure: ``build(catalog, today)`` returns ``{path: text}`` and touches nothing, so
the tests can render the whole repository from a fixture and compare bytes.

The layout is shaped by one requirement — **the first screen of the README must
tell a visitor who this list is for and take them to their loop in one click** —
and by one constraint: GitHub stops rendering a markdown file at 512,000 bytes.
So the README is an index (audience matrix, companies, the newest rows at AI
labs, quant firms and MAANG+) and the rows live in capped, paginated pages.
"""

from __future__ import annotations

import csv
import io
import json
from collections import Counter
from datetime import date

from model import (
    FORMAT_SHORT,
    FORMATS,
    GROUP_BY_ID,
    GROUPS,
    GUIDE_ROLES,
    LEVEL_SHORT,
    MIN_LIST_ROWS,
    MONTHS,
    RECENT_DAYS,
    ROUND_EMOJI,
    ROUND_LABELS,
    ROUND_SHORT,
    ROUNDS,
    TRACK_BY_ID,
    TRACKS,
    Catalog,
    Question,
    group_of,
    in_group,
    is_future,
    is_recent,
    list_slug,
    newest_first,
    seen_text,
)

SITE = "https://trueinterview.io"
REPO = "kevin-2023-code/Tech-OA-Questions"
SISTER = "https://github.com/kevin-2023-code/Tech-Interview-Questions"
NEW_GRAD = "https://github.com/kevin-2023-code/New-Grad-Opportunities"
INTERNSHIPS = "https://github.com/kevin-2023-code/Internship-Opportunities"
SUBMIT = f"https://github.com/{REPO}/issues/new?template=oa-report.yml"

GENERATED = "<!-- Generated by scripts/sync.py from the TrueInterview catalog. Do not edit by hand: the next sync overwrites it. -->"

README_ROWS = 120
PAGE_ROWS = 400

#: GitHub truncates a rendered markdown file at 512,000 bytes. Both budgets leave
#: a wide margin, and sync.py writes NOTHING when one is exceeded.
README_MAX_BYTES = 160_000
PAGE_MAX_BYTES = 400_000

LEGEND = "Newest first · 🔥 reported in the last 14 days · 🆕 last 45 days · **Level** = the seniority the loop was reported at · a dash means not recorded"

GROUP_TITLES = {"ai-labs": "AI Labs", "quant": "Quant Firms", "maang": "MAANG+"}
GROUP_ADJ = {"ai-labs": "AI Lab", "quant": "Quant Firm", "maang": "MAANG+"}
TRACK_TITLES = {
    "senior-staff": "Senior & Staff+ Engineer",
    "staff": "Staff+ Engineer",
    "ml-research": "ML Engineer & Research Scientist",
    "quant-roles": "Quant Researcher & Developer",
    "all": "",
}

FORMAT_TITLES = {
    "algorithm": "Coding (Algorithm)",
    "system-design": "System Design",
    "object-oriented-programming": "Object-Oriented & Low-Level Design",
    "sql": "SQL",
    "ai-coding": "AI Coding",
}


# ── Cells ────────────────────────────────────────────────────────────────────


def esc(text: str) -> str:
    """Make free text safe inside a table cell and a link label."""
    return (
        text.replace("\\", "\\\\")
        .replace("|", "\\|")
        .replace("[", "\\[")
        .replace("]", "\\]")
        .replace("<", "&lt;")
        .replace("\n", " ")
    )


def num(n: int) -> str:
    return f"{n:,}"


def _count(n: int) -> str:
    return num(n) if n else "—"


def company_cell(q: Question, root: str, skip: str | None = None) -> str:
    parts = []
    for name, key in zip(q.companies, q.company_keys):
        if key == skip:
            continue
        parts.append(f"[{esc(name)}]({root}companies/{key}.md)")
    if not parts:
        return "—"
    shown = parts[:3]
    if len(parts) > 3:
        shown.append(f"+{len(parts) - 3}")
    first = f"**{shown[0]}**" if skip is None else shown[0]
    return " / ".join([first, *shown[1:]])


def level_cell(q: Question) -> str:
    return " · ".join(LEVEL_SHORT[level] for level in q.levels) or "—"


def round_cell(q: Question) -> str:
    return " · ".join(ROUND_SHORT[r] for r in q.rounds) or "—"


def practice_cell(q: Question) -> str:
    return f"[![Free][f]]({q.url})" if q.free else f"[![Practice][p]]({q.url})"


def table(questions: list[Question], today: date, root: str, company: str | None = None) -> list[str]:
    head = "| Question | Round | Level | Format | Solve | Seen |" if company else "| Company | Question | Round | Level | Format | Solve | Seen |"
    rule = "| :-- | :-- | :-- | :-- | :-: | :-- |" if company else "| :-- | :-- | :-- | :-- | :-- | :-: | :-- |"
    lines = [
        f"[p]: {root}assets/practice.svg",
        f"[f]: {root}assets/free.svg",
        "",
        head,
        rule,
    ]
    for q in questions:
        cells = []
        if company is None:
            cells.append(company_cell(q, root))
        title = f"[{esc(q.title)}]({q.url})"
        if company is not None:
            also = company_cell(q, root, skip=company)
            if also != "—":
                title += f"<br><sub>also {also}</sub>"
        cells += [title, round_cell(q), level_cell(q), FORMAT_SHORT.get(q.format, q.format), practice_cell(q), seen_text(q, today)]
        lines.append("| " + " | ".join(cells) + " |")
    return lines


# ── Shared blocks ────────────────────────────────────────────────────────────


def counts_line(questions: list[Question], today: date) -> str:
    total = len(questions)
    exp = sum(1 for q in questions if TRACK_BY_ID["senior-staff"].test(q))
    recent = sum(1 for q in questions if is_recent(q, today))
    free = sum(1 for q in questions if q.free)
    parts = [f"**{num(total)} questions**", f"{num(exp)} at Senior/Staff+", f"{num(recent)} reported in the last {RECENT_DAYS} days", f"{num(free)} free to solve"]
    return " · ".join(parts)


def rounds_line(questions: list[Question], root: str) -> str:
    counts = Counter(r for q in questions for r in q.rounds)
    parts = [f"{ROUND_EMOJI[r]} {ROUND_SHORT[r]} ({num(counts[r])})" for r in ROUNDS if counts[r]]
    return "**Rounds:** " + " · ".join(parts) if parts else ""


def top_companies(
    questions: list[Question], labels_by_key: dict[str, str], limit: int, only: set[str] | None = None
) -> list[tuple[str, str, int]]:
    counts: Counter[str] = Counter(k for q in questions for k in q.company_keys if only is None or k in only)
    ordered = sorted(counts.items(), key=lambda kv: (-kv[1], labels_by_key.get(kv[0], kv[0]).lower()))
    return [(key, labels_by_key.get(key, key), n) for key, n in ordered[:limit]]


def company_links(items: list[tuple[str, str, int]], root: str) -> str:
    return " · ".join(f"[{esc(name)} ({num(n)})]({root}companies/{key}.md)" for key, name, n in items)


def paginate(path_stem: str, header: list[str], questions: list[Question], today: date, root: str, company: str | None = None) -> dict[str, str]:
    """``<stem>.md``, ``<stem>-2.md``, … each capped at PAGE_ROWS rows."""
    pages = [questions[i : i + PAGE_ROWS] for i in range(0, len(questions), PAGE_ROWS)] or [[]]
    name = path_stem.rsplit("/", 1)[-1]
    files = {}
    for index, rows in enumerate(pages, start=1):
        path = f"{path_stem}.md" if index == 1 else f"{path_stem}-{index}.md"
        nav = []
        if len(pages) > 1:
            links = []
            for n in range(1, len(pages) + 1):
                target = f"{name}.md" if n == 1 else f"{name}-{n}.md"
                links.append(f"**{n}**" if n == index else f"[{n}]({target})")
            nav = [f"<sub>Page {' · '.join(links)}</sub>", ""]
        body = [*header, *nav]
        if rows:
            body += [f"<sub>{LEGEND}</sub>", "", *table(rows, today, root, company), ""]
        else:
            body += ["_Nothing here yet._", ""]
        body += nav
        files[path] = "\n".join(body).rstrip() + "\n"
    return files


def labels_by_key(catalog: Catalog) -> dict[str, str]:
    out: dict[str, str] = {}
    for q in catalog.questions:
        for key, name in zip(q.company_keys, q.companies):
            out.setdefault(key, name)
    return out


# ── Lists (the matrix cells) ─────────────────────────────────────────────────


def list_title(track: str, group: str | None) -> str:
    who = TRACK_TITLES[track]
    if group is None:
        return f"{who} OA & Interview Questions (2026)".strip()
    if track == "all":
        return f"{GROUP_ADJ[group]} OA & Interview Questions (2026)"
    return f"{who} Interview Questions at {GROUP_TITLES[group]} (2026)"


def cut(catalog: Catalog, track: str, group: str | None) -> list[Question]:
    test = TRACK_BY_ID[track].test
    return [q for q in catalog.questions if test(q) and in_group(q, group)]


def build_lists(catalog: Catalog, today: date) -> dict[str, str]:
    names = labels_by_key(catalog)
    groups_of = company_groups(catalog)
    files: dict[str, str] = {}
    index_rows = []
    for track in TRACKS:
        for group in [*(g.id for g in GROUPS), None]:
            if track.id == "all" and group is None:
                continue  # that is the question bank
            rows = newest_first(cut(catalog, track.id, group), today)
            if len(rows) < MIN_LIST_ROWS:
                continue
            slug = list_slug(track.id, group)
            title = list_title(track.id, group)
            rules = [f"> **Who:** {track.rule}"] if track.id != "all" else []
            if group:
                rules.append(f"> **Where:** {GROUP_BY_ID[group].rule}")
            header = [
                GENERATED,
                "",
                f"# {title}",
                "",
                f"[← Home](../README.md) · [Every list](README.md) · [Every company](../companies/README.md) · [Submit an OA]({SUBMIT})",
                "",
                *[line for rule in rules for line in (rule, ">")][:-1],
                "",
                counts_line(rows, today),
                "",
                rounds_line(rows, "../"),
                "",
                "**Companies:** " + company_links(top_companies(rows, names, 15, _members(groups_of, group)), "../"),
                "",
            ]
            files.update(paginate(f"lists/{slug}", header, rows, today, "../"))
            index_rows.append((track, group, slug, title, len(rows)))

    free = newest_first([q for q in catalog.questions if q.free], today)
    header = [
        GENERATED,
        "",
        "# Free OA & Interview Questions — Solve Without a Paid Plan",
        "",
        "[← Home](../README.md) · [Every list](README.md) · [Every company](../companies/README.md)",
        "",
        "> Every question the catalog opens without a paid plan: the full statement, a runnable editor and, on coding, OOD and SQL, a judged verdict. The site decides what is free; this page follows it on every sync.",
        "",
        counts_line(free, today),
        "",
        "**Companies:** " + company_links(top_companies(free, names, 15), "../"),
        "",
    ]
    files.update(paginate("lists/free", header, free, today, "../"))

    lines = [GENERATED, "", "# Every list, and exactly what it selects", "", "[← Home](../README.md)", ""]
    lines += ["Each list is one cell of the matrix on the front page: **who you are** × **where you are interviewing**. "
              f"A cut with fewer than {MIN_LIST_ROWS} questions gets no page.", ""]
    lines += ["## Who you are", ""]
    lines += [f"- {t.emoji} **{t.label}** — {t.rule}" for t in TRACKS]
    lines += ["", "A question carries the levels and roles **the catalog recorded for it** — reported by the candidate, or inferred from their write-up. "
              "A question with no level on record is in no level list: unclassified is not the same as \"every level\".", ""]
    lines += ["## Where you are interviewing", ""]
    lines += [f"- {g.emoji} **{g.label}** — {g.rule}" for g in GROUPS]
    lines += ["", "## The lists", "", "| List | Questions |", "| :-- | --: |"]
    for track, group, slug, title, n in index_rows:
        lines.append(f"| [{esc(title)}]({slug}.md) | {num(n)} |")
    lines.append(f"| [Free to solve](free.md) | {num(len(free))} |")
    files["lists/README.md"] = "\n".join(lines) + "\n"
    return files


# ── Rounds, formats, the full bank ───────────────────────────────────────────


def build_rounds_formats_bank(catalog: Catalog, today: date) -> dict[str, str]:
    names = labels_by_key(catalog)
    files: dict[str, str] = {}
    for r in ROUNDS:
        rows = newest_first([q for q in catalog.questions if r in q.rounds], today)
        if not rows:
            continue
        title = "OA (Online Assessment) Questions (2026)" if r == "oa" else f"{ROUND_LABELS[r]} Interview Questions (2026)"
        header = [
            GENERATED, "", f"# {title}", "",
            "[← Home](../README.md) · [Every company](../companies/README.md) · [Every list](../lists/README.md)", "",
            counts_line(rows, today), "",
            "**By employer group:** " + " · ".join(f"{g.emoji} {g.label} ({num(sum(1 for q in rows if g.id in q.groups))})" for g in GROUPS), "",
            "**Companies:** " + company_links(top_companies(rows, names, 15), "../"), "",
        ]
        files.update(paginate(f"rounds/{r}", header, rows, today, "../"))
    for fmt in FORMATS:
        rows = newest_first([q for q in catalog.questions if q.format == fmt], today)
        if not rows:
            continue
        header = [
            GENERATED, "", f"# {FORMAT_TITLES[fmt]} Interview Questions (2026)", "",
            "[← Home](../README.md) · [Every company](../companies/README.md) · [Every list](../lists/README.md)", "",
            counts_line(rows, today), "", rounds_line(rows, "../"), "",
            "**Companies:** " + company_links(top_companies(rows, names, 15), "../"), "",
        ]
        files.update(paginate(f"formats/{fmt}", header, rows, today, "../"))
    rows = newest_first(catalog.questions, today)
    header = [
        GENERATED, "", "# Every OA & Interview Question, Newest First", "",
        "[← Home](../README.md) · [Every company](../companies/README.md) · [Every list](../lists/README.md)", "",
        counts_line(rows, today), "", rounds_line(rows, "../"), "",
    ]
    files.update(paginate("question-bank/README", header, rows, today, "../"))
    # paginate names page 2 after the stem; the bank's stem is README, so its
    # later pages are README-2.md … which reads oddly in a URL. Rename them.
    renamed = {}
    for path, text in files.items():
        if path.startswith("question-bank/README-"):
            n = path[len("question-bank/README-") : -3]
            renamed[f"question-bank/page-{n}.md"] = text
        else:
            renamed[path] = text
    out = {}
    for path, text in renamed.items():
        if path.startswith("question-bank/"):
            for n in range(2, 200):
                text = text.replace(f"(README-{n}.md)", f"(page-{n}.md)")
        out[path] = text
    return out


# ── Companies ────────────────────────────────────────────────────────────────


def build_companies(catalog: Catalog, today: date) -> dict[str, str]:
    names = labels_by_key(catalog)
    by_company: dict[str, list[Question]] = {}
    for q in catalog.questions:
        for key in dict.fromkeys(q.company_keys):
            by_company.setdefault(key, []).append(q)
    guides: dict[str, dict[str, str]] = {}
    for g in catalog.guides:
        guides.setdefault(g.company_key, {}).setdefault(g.role, g.url)

    groups_of = company_groups(catalog)
    files: dict[str, str] = {}
    index = []
    for key, qs in by_company.items():
        rows = newest_first(qs, today)
        name = names.get(key, key)
        group = GROUP_BY_ID.get(groups_of.get(key) or "")
        tracks = {t.id: sum(1 for q in rows if t.test(q)) for t in TRACKS if t.id in ("senior-staff", "ml-research", "quant-roles")}
        chips = [f"{group.emoji} {group.label}"] if group else []
        chips.append(f"**{num(len(rows))} questions**")
        chips += [f"{TRACK_BY_ID[t].label} {num(n)}" for t, n in tracks.items() if n]
        dated = [q.seen for q in rows if q.seen and not is_future(q, today)]
        if dated:
            last = max(dated)
            chips.append(f"last reported {MONTHS[last.month - 1]} {last.year}")
        guide_links = []
        own = guides.get(key, {})
        if "overview" in own:
            guide_links.append(f"[Overview]({own['overview']})")
        guide_links += [f"[{label}]({own[role]})" for role, label in GUIDE_ROLES.items() if role in own]
        site = catalog.site_company_urls.get(key, f"{SITE}/problems/company/{key}")
        header = [
            GENERATED, "",
            f"# {name} OA & Interview Questions (2026)", "",
            f"[← Home](../README.md) · [Every company](README.md) · [Practice {esc(name)} on TrueInterview]({site}) · [How {esc(name)} interviews]({SISTER}/blob/main/companies/{key}/README.md)", "",
            " · ".join(chips), "",
            rounds_line(rows, "../"), "",
        ]
        if guide_links:
            header += [f"**📖 Loop guides:** " + " · ".join(guide_links), ""]
        files.update(paginate(f"companies/{key}", header, rows, today, "../", company=key))
        index.append((key, name, group, rows, tracks))

    index.sort(key=lambda item: (-len(item[3]), item[1].lower()))
    lines = [GENERATED, "", "# Every Company — OA & Interview Questions", "", "[← Home](../README.md) · [Every list](../lists/README.md)", "",
             "Counts are per company: a question reported at three employers is on three pages.", "",
             "| Company | Group | Questions | Senior/Staff+ | ML & research | Quant roles | Last reported |",
             "| :-- | :-- | --: | --: | --: | --: | :-- |"]
    for key, name, group, rows, tracks in index:
        dated = [q.seen for q in rows if q.seen and not is_future(q, today)]
        last = f"{MONTHS[max(dated).month - 1]} {max(dated).year}" if dated else "—"
        lines.append(
            f"| [{esc(name)}]({key}.md) | {f'{group.emoji} {group.label}' if group else '—'} | {num(len(rows))} | "
            f"{_count(tracks['senior-staff'])} | {_count(tracks['ml-research'])} | {_count(tracks['quant-roles'])} | {last} |"
        )
    files["companies/README.md"] = "\n".join(lines) + "\n"
    return files


def _members(groups_of: dict[str, str | None], group: str | None) -> set[str] | None:
    return None if group is None else {key for key, g in groups_of.items() if g == group}


def company_groups(catalog: Catalog) -> dict[str, str | None]:
    """Each company page's employer group, from the company itself — never from
    the other employers a shared question happens to name."""
    out: dict[str, str | None] = {}
    for q in catalog.questions:
        for name, key in zip(q.companies, q.company_keys):
            if key not in out:
                out[key] = group_of(name, catalog.labels)
    return out


# ── Data exports ─────────────────────────────────────────────────────────────

EXPORT_FIELDS = ("slug", "title", "url", "companies", "format", "difficulty", "rounds", "seniority", "roles", "role_titles",
                 "reported", "last_reported", "access_tier", "topics")


def export_record(q: Question) -> dict:
    return {
        "slug": q.slug,
        "title": q.title,
        "url": q.url,
        "companies": list(q.companies),
        "format": q.format,
        "difficulty": q.difficulty,
        "rounds": list(q.rounds),
        "seniority": list(q.levels),
        "roles": list(q.roles),
        "role_titles": list(q.role_titles),
        "reported": q.reported,
        "last_reported": q.last_reported,
        "access_tier": q.access_tier,
        "topics": list(q.topics),
    }


def build_data(catalog: Catalog) -> dict[str, str]:
    records = [export_record(q) for q in catalog.questions]
    jsonl = "".join(json.dumps(r, ensure_ascii=False, sort_keys=True) + "\n" for r in records)
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(EXPORT_FIELDS)
    for r in records:
        writer.writerow(["; ".join(v) if isinstance(v, list) else ("" if v is None else v) for v in (r[f] for f in EXPORT_FIELDS)])
    return {"data/questions.jsonl": jsonl, "data/questions.csv": buffer.getvalue()}


# ── README ───────────────────────────────────────────────────────────────────


def matrix(catalog: Catalog) -> list[str]:
    cols = [*GROUPS, None]
    head = "| Who you are ↓ · Where you're interviewing → | " + " | ".join(f"{g.emoji} **{g.label}**" for g in GROUPS) + " | 🌐 **All companies** |"
    lines = [head, "| :-- | " + " | ".join(":-:" for _ in cols) + " |"]
    for track in TRACKS:
        cells = [f"{track.emoji} **{track.label}**<br><sub>{track.hint}</sub>"]
        for group in cols:
            gid = group.id if group else None
            n = len(cut(catalog, track.id, gid))
            if track.id == "all" and gid is None:
                cells.append(f"[**{num(n)}**](question-bank/README.md)")
            elif n >= MIN_LIST_ROWS:
                cells.append(f"[**{num(n)}**](lists/{list_slug(track.id, gid)}.md)")
            else:
                cells.append("—")
        lines.append("| " + " | ".join(cells) + " |")
    return lines


def guides_table(catalog: Catalog, names: dict[str, str], counts: Counter, groups_of: dict[str, str | None]) -> list[str]:
    roles = [r for r in ("Software Engineer", "Machine Learning Engineer", "Research Scientist", "AI Engineer", "Infrastructure Engineer", "Quantitative Finance")
             if any(g.role == r for g in catalog.guides)]
    by_company: dict[str, dict[str, str]] = {}
    for g in catalog.guides:
        by_company.setdefault(g.company_key, {}).setdefault(g.role, g.url)
    rows = []
    for group in GROUPS:
        keys = sorted({k for q in catalog.questions for k in q.company_keys if k in by_company and groups_of.get(k) == group.id},
                      key=lambda k: (-counts[k], names.get(k, k).lower()))
        for key in keys:
            own = by_company[key]
            if not any(r in own for r in roles):
                continue
            cells = [f"{group.emoji} [{esc(names.get(key, key))}](companies/{key}.md)"]
            cells.append(f"[📖]({own['overview']})" if "overview" in own else "—")
            cells += [f"[📖]({own[r]})" if r in own else "—" for r in roles]
            rows.append("| " + " | ".join(cells) + " |")
    if not rows:
        return []
    head = "| Company | Overview | " + " | ".join(GUIDE_ROLES[r] for r in roles) + " |"
    return [head, "| :-- | " + " | ".join(":-:" for _ in range(len(roles) + 1)) + " |", *rows]


def pick_reports(catalog: Catalog, groups_of: dict[str, str | None], limit: int = 10, per_company: int = 2) -> list:
    """Senior, Staff+ and research/quant reports, newest first — employers in the
    three groups ahead of the rest, and never more than two from one company, so
    a day on which forty reports land from one employer does not fill the block."""
    wanted = [r for r in catalog.reports if r.level in ("senior", "staff-plus") or r.role_title in REPORT_TITLES]
    ordered = sorted(enumerate(wanted), key=lambda ir: (groups_of.get(ir[1].company_key) is None, ir[0]))
    picked, seen = [], Counter()
    for _, r in ordered:
        if seen[r.company_key] >= per_company:
            continue
        seen[r.company_key] += 1
        picked.append(r)
        if len(picked) == limit:
            break
    return picked


REPORT_TITLES = {"Research Scientist", "Machine Learning Engineer", "AI Engineer", "Quantitative Researcher", "Quantitative Developer", "Quantitative Trader"}


def build_readme(catalog: Catalog, today: date) -> str:
    names = labels_by_key(catalog)
    qs = catalog.questions
    counts: Counter[str] = Counter(k for q in qs for k in dict.fromkeys(q.company_keys))
    n_companies = len(counts)
    senior = sum(1 for q in qs if TRACK_BY_ID["senior-staff"].test(q))
    ml = sum(1 for q in qs if TRACK_BY_ID["ml-research"].test(q))
    quant = sum(1 for q in qs if TRACK_BY_ID["quant-roles"].test(q))
    recent = sum(1 for q in qs if is_recent(q, today))
    free = sum(1 for q in qs if q.free)
    oa = sum(1 for q in qs if "oa" in q.rounds)
    groups_of = company_groups(catalog)

    def examples(group: str, k: int) -> str:
        keys = [key for key, _ in counts.most_common() if groups_of.get(key) == group][:k]
        return ", ".join(names.get(key, key) for key in keys)

    lines = [
        GENERATED,
        "",
        '<div align="center">',
        "",
        "# 2026 & 2027 Tech OA & Interview Questions for Experienced Hires",
        "",
        "### 🎯 Senior · Staff+ · ML & Research Scientist · Quant — at 🧠 AI Labs · 📈 Quant Firms · 🏛️ MAANG",
        "",
        f"Real OA, phone-screen and onsite questions candidates reported at **{examples('ai-labs', 3)}**, **{examples('quant', 3)}**, "
        f"**{examples('maang', 3)}** and {num(n_companies - 3)} more — **every row tagged with the level and the round it was asked in.** Synced hourly.",
        "",
        f"**{num(len(qs))} questions** · **{num(senior)} at Senior/Staff+** · **{num(ml)} ML & research** · **{num(quant)} quant** · "
        f"{num(oa)} OA · {num(recent)} reported in the last {RECENT_DAYS} days · {num(free)} free",
        "",
        f"[**▶ Practice on TrueInterview**]({SITE}/problems) &nbsp;·&nbsp; [**📝 Submit an OA**]({SUBMIT}) &nbsp;·&nbsp; "
        f"[**🗣️ Interview reports**]({SITE}/interviews) &nbsp;·&nbsp; [**📦 The data (CSV)**](data/questions.csv)",
        "",
        "</div>",
        "",
        "## 🎯 Find your loop in one click",
        "",
        "<sub>Rows: **who you are**. Columns: **where you're interviewing**. Each number opens that list, newest first. "
        "[What exactly each one selects →](lists/README.md)</sub>",
        "",
        *matrix(catalog),
        "",
        _round_links(qs),
        "",
        "**By format:** " + " · ".join(f"[{FORMAT_SHORT[f]} ({num(sum(1 for q in qs if q.format == f))})](formats/{f}.md)" for f in FORMATS if any(q.format == f for q in qs))
        + f" &nbsp;·&nbsp; [🆓 Free to solve ({num(free)})](lists/free.md)",
        "",
        *insights_block(catalog),
        "## 🏢 Companies",
        "",
    ]
    for group in GROUPS:
        keys = [key for key, _ in counts.most_common() if groups_of.get(key) == group.id]
        keys.sort(key=lambda k: (-counts[k], names.get(k, k).lower()))
        lines += [f"**{group.emoji} {group.label}:** " + " · ".join(f"[{esc(names.get(k, k))} ({num(counts[k])})](companies/{k}.md)" for k in keys), ""]
    others = sorted((k for k in counts if groups_of.get(k) is None), key=lambda k: (-counts[k], names.get(k, k).lower()))
    if others:
        lines += ["<details>", f"<summary><b>🌐 + {len(others)} more companies</b></summary>", "",
                  " · ".join(f"[{esc(names.get(k, k))} ({num(counts[k])})](companies/{k}.md)" for k in others), "", "</details>", ""]
    lines += ["[**Every company, with Senior/Staff+ and ML counts →**](companies/README.md)", ""]

    target = newest_first([q for q in qs if q.groups and not is_future(q, today) and q.seen], today)[:README_ROWS]
    lines += [
        "## 🔥 Latest at AI labs, quant firms & MAANG",
        "",
        f"<sub>{LEGEND}. [Every company, newest first →](question-bank/README.md)</sub>",
        "",
        *table(target, today, ""),
        "",
        f"[**All {num(len(qs))} questions, every company, newest first →**](question-bank/README.md)",
        "",
    ]

    guide_lines = guides_table(catalog, names, counts, groups_of)
    if guide_lines:
        lines += [
            "## 📖 How the loop runs — by role",
            "",
            "A Research Scientist loop at OpenAI is not a SWE loop at OpenAI. These write-ups take one role at one company: "
            "the rounds in order, what each one grades, and the questions candidates reported in it. Free to read.",
            "",
            *guide_lines,
            "",
        ]

    reports = pick_reports(catalog, groups_of)
    if reports:
        lines += [
            "## 🗣️ Latest Senior, Staff & research interview reports",
            "",
            "What candidates said happened in the room — newest first, AI labs, quant firms and MAANG+ ahead of the rest, at most two per company.",
            "",
            "| Company | Role | Level | Report | Posted |",
            "| :-- | :-- | :-- | :-- | :-- |",
        ]
        for r in reports:
            posted = f"{MONTHS[r.posted.month - 1]} {r.posted.day}, {r.posted.year}" if r.posted else "—"
            level = LEVEL_SHORT.get(r.level, "—") if r.level else "—"
            lines.append(f"| **{esc(r.company)}** | {esc(r.role_title or '—')} | {level} | [{esc(r.title)}]({r.url}) | {posted} |")
        total = f"{num(catalog.reports_total)} reports" if catalog.reports_total else "Every report"
        lines += ["", f"[**{total} on the board →**]({SITE}/interviews)", ""]

    lines += [
        "## Why this list",
        "",
        "| | |",
        "| :-- | :-- |",
        "| 🎚️ **Level on every row** | Senior, Staff+ or Mid — the seniority the loop was reported at, so an L6 candidate is not reading new-grad OAs. |",
        "| 🧭 **Round on every row** | OA, phone screen, onsite or take-home: practise for the round you actually have next. |",
        "| 🔬 **Research & quant tracks** | ML engineer, research scientist and quant researcher/developer questions, cut out of the bank instead of buried in it. |",
        "| 🔥 **Fresh, automatically** | Synced from the live catalog every hour; 🔥 and 🆕 expire on their own, so the top of every list is what is being asked now. |",
        "| ▶ **Runnable, not a screenshot** | Every title opens the real problem in an editor; coding, OOD and SQL get a judged verdict. **Free** rows open without a paid plan. |",
        "| 📦 **Data, not just markdown** | [`data/questions.csv`](data/questions.csv) and [`data/questions.jsonl`](data/questions.jsonl): every row with its companies, round, level and role. |",
        "",
        "## Contribute",
        "",
        f"Saw a question in an OA or a loop? [**Submit it**]({SUBMIT}) — company, role, level, round and a short source-safe summary. "
        "No screenshots, no copied problem statements: see [CONTRIBUTING.md](CONTRIBUTING.md). "
        "Rows are generated from the catalog, so please do not open a pull request against a table.",
        "",
        "**Built something on the data?** A study planner, a Discord bot, a chart — open an issue with the link and we will list it here. "
        "[`data/questions.csv`](data/questions.csv) and [`data/questions.jsonl`](data/questions.jsonl) carry every row with its companies, round, level and role, refreshed hourly.",
        "",
        "## More from TrueInterview",
        "",
        f"- [**Tech-Interview-Questions**]({SISTER}) — every company's loop, interview-process guides and what companies are asking, counted.",
        f"- [**New-Grad-Opportunities**]({NEW_GRAD}) · [**Internship-Opportunities**]({INTERNSHIPS}) — open roles, refreshed daily.",
        "",
        "<sub>Questions are listed by title and metadata only; statements and solutions live on "
        f"[TrueInterview]({SITE}). Code in this repository is MIT-licensed.</sub>",
    ]
    return "\n".join(lines) + "\n"


LEVEL_BANDS = (
    ("staff-plus", "🚀 Staff+"),
    ("senior", "🎯 Senior"),
    ("junior", "Mid"),
    ("new-grad", "New grad & intern"),
)
INSIGHT_FORMATS = ("algorithm", "system-design", "object-oriented-programming", "sql", "ai-coding")


def _top_band(q: Question) -> str | None:
    """The most senior rung a question was reported at, folded into four bands."""
    if "staff-plus" in q.levels:
        return "staff-plus"
    if "senior" in q.levels:
        return "senior"
    if "junior" in q.levels:
        return "junior"
    if "new-grad" in q.levels or "intern" in q.levels:
        return "new-grad"
    return None


def _share(part: int, whole: int) -> str:
    return f"{round(100 * part / whole)}%" if whole else "—"


def insights_block(catalog: Catalog) -> list[str]:
    """What the loop is made of at each level, and how much of it is an OA at each
    kind of employer — counted from the bank on every sync, never asserted. Every
    share is over the row count printed beside it."""
    qs = catalog.questions
    head = "| | Questions | " + " | ".join(FORMAT_SHORT[f] for f in INSIGHT_FORMATS) + " |"
    rule = "| :-- | --: | " + " | ".join("--:" for _ in INSIGHT_FORMATS) + " |"
    level_rows = []
    for band, label in LEVEL_BANDS:
        rows = [q for q in qs if _top_band(q) == band]
        if not rows:
            continue
        counts = Counter(q.format for q in rows)
        level_rows.append(f"| {label} | {num(len(rows))} | " + " | ".join(_share(counts[f], len(rows)) for f in INSIGHT_FORMATS) + " |")
    group_rows = []
    for group in GROUPS:
        rows = [q for q in qs if group.id in q.groups]
        if not rows:
            continue
        oa = sum(1 for q in rows if "oa" in q.rounds)
        counts = Counter(q.format for q in rows)
        group_rows.append(f"| {group.emoji} {group.label} | {num(len(rows))} | {_share(oa, len(rows))} | "
                          + " | ".join(_share(counts[f], len(rows)) for f in ("algorithm", "system-design", "object-oriented-programming")) + " |")
    if not level_rows:
        return []
    lines = [
        "## 📊 What changes as you go up a level",
        "",
        "<sub>Share of each format among the questions reported at that level (a question counts once, at the most senior level it was reported at). Recounted every sync.</sub>",
        "",
        head, rule, *level_rows, "",
    ]
    if group_rows:
        lines += [
            "<sub>And by employer: how much of what candidates reported came from an **OA round**, and the format mix.</sub>",
            "",
            "| | Questions | From an OA | Coding | System design | OOD / LLD |",
            "| :-- | --: | --: | --: | --: | --: |",
            *group_rows, "",
        ]
    return lines


def _round_links(qs) -> str:
    counts = Counter(r for q in qs for r in q.rounds)
    return "**By round:** " + " · ".join(
        f"[{ROUND_EMOJI[r]} {ROUND_SHORT[r]} ({num(counts[r])})](rounds/{r}.md)" for r in ROUNDS if counts[r]
    )


# ── Everything ───────────────────────────────────────────────────────────────


def build(catalog: Catalog, today: date) -> dict[str, str]:
    files: dict[str, str] = {"README.md": build_readme(catalog, today)}
    files.update(build_lists(catalog, today))
    files.update(build_rounds_formats_bank(catalog, today))
    files.update(build_companies(catalog, today))
    files.update(build_data(catalog))
    return files


def over_budget(files: dict[str, str]) -> list[str]:
    problems = []
    for path, text in files.items():
        if not path.endswith(".md"):
            continue
        size = len(text.encode("utf-8"))
        limit = README_MAX_BYTES if path == "README.md" else PAGE_MAX_BYTES
        if size > limit:
            problems.append(f"{path}: {size:,} bytes > {limit:,}")
    return problems
